'use client';

import Link from 'next/link';
import Magnetic from '../ui/Magnetic';

export default function Navbar() {
  const navLinks = [
    { name: 'Home', href: '#home' },
    { name: 'About', href: '#about' },
    { name: 'Services', href: '#services' },
    { name: 'Portfolio', href: '#portfolio' },
    { name: 'Contact', href: '#contact' },
  ];

  const handleScroll = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    const targetId = href.replace('#', '');
    const elem = document.getElementById(targetId);
    elem?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <nav className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] w-[95%] max-w-5xl">
      <div className="bg-[#000000]/40 backdrop-blur-xl border border-white/5 rounded-full px-8 py-4 flex items-center justify-between shadow-2xl">
        {/* Brand */}
        <Link
          href="#home"
          onClick={(e) => handleScroll(e, '#home')}
          className="group flex items-center gap-2"
        >
          <div className="w-2 h-2 rounded-full bg-[#B6B09F] group-hover:scale-150 transition-transform duration-500" />
          <span className="text-[10px] font-black text-[#F2F2F2] uppercase tracking-[0.5em]">SyntaxWeb</span>
        </Link>

        {/* Desktop Links */}
        <div className="hidden md:flex items-center gap-12">
          {navLinks.map((link) => (
            <Magnetic key={link.name}>
              <a
                href={link.href}
                onClick={(e) => handleScroll(e, link.href)}
                className="text-[10px] font-black text-[#F2F2F2]/50 hover:text-[#B6B09F] uppercase tracking-[0.4em] transition-colors duration-500 block py-2 px-1"
              >
                {link.name}
              </a>
            </Magnetic>
          ))}
        </div>

        {/* CTA */}
        <Magnetic>
          <a
            href="#contact"
            onClick={(e) => handleScroll(e, '#contact')}
            className="bg-[#F2F2F2] hover:bg-[#B6B09F] text-black text-[10px] font-black uppercase tracking-widest px-8 py-3 rounded-full transition-all duration-500 hover:scale-105 active:scale-95"
          >
            Start Project
          </a>
        </Magnetic>
      </div>
    </nav>
  );
}
